#!/usr/bin/env bash
# Copies the native Android pieces into the project generated by `flutter create`.
set -euo pipefail

PKG_DIR=android/app/src/main/kotlin/app/aether/aether_gui
mkdir -p "$PKG_DIR" android/app/src/main/java/hev/htproxy

cp android_overlay/kotlin/*.kt "$PKG_DIR/"
cp android_overlay/java/hev/htproxy/TProxyService.java android/app/src/main/java/hev/htproxy/
cp android_overlay/AndroidManifest.xml android/app/src/main/AndroidManifest.xml

F=android/app/build.gradle
if [ ! -f "$F" ]; then
  echo "Expected a Groovy android/app/build.gradle (Flutter 3.27.x). Found a different layout." >&2
  exit 1
fi

cat >> "$F" <<'GRADLE'

android {
    defaultConfig {
        minSdkVersion 24
    }
    packaging {
        // Aether and tun2socks are executed/loaded from nativeLibraryDir, so they must be extracted.
        jniLibs {
            useLegacyPackaging = true
        }
    }
}
GRADLE

rm -rf test
echo "overlay applied"
